pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // bound amount to a reasonable value for deposit
        amount = bound(amount, 0, 1 ether);
        vm.deal(address(this), amount);

        // deposit some ether
        c.deposit{value: amount}();

        // Now check the invariant: contract balance should equal total deposits
        // Since we only deposited once, contract balance should equal amount
        // The bug in withdraw would break this property if we had withdrawn, but we only deposit here
        // However, the bug is in withdraw, so we need to incorporate a withdraw call to expose it
        // Let's withdraw the full balance
        uint256 balanceBefore = address(c).balance;
        c.withdraw(amount);
        uint256 balanceAfter = address(c).balance;

        // The invariant: after a withdraw of 'amount', the contract balance should be unchanged if amount == 0,
        // but if amount > 0, the bug attempts to send amount+1, so contract balance will decrease by amount+1
        // This will cause the contract to have insufficient balance if amount == address(this).balance
        // The general rule: after withdraw, the contract balance should equal previous balance minus amount
        // But due to the bug, it will be one less (if amount == balanceBefore) or revert
        bool success;
        if (amount == balanceBefore) {
            // The buggy version will try to send amount+1 > balanceBefore -> revert
            // The correct version sends amount == balanceBefore -> success
            // We catch the revert in a try/catch
            try c.withdraw(amount) {
                success = true;
            } catch {
                success = false;
            }
            assertTrue(!success, "Buggy version should revert when amount == balance");
        } else {
            c.withdraw(amount);
            assertTrue(address(c).balance == balanceBefore - amount, "Withdraw should reduce balance by amount");
        }
    }
}

