import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2) public {
        // Precondition: deposits must not overflow balances
        vm.assume(amount1 > 0 && amount1 <= type(uint256).max - address(this).balance);
        vm.assume(amount2 > 0 && amount2 <= type(uint256).max - address(this).balance);

        address user = address(0x1234);
        vm.deal(user, amount1 + amount2);

        vm.prank(user);
        c.deposit{value: amount1}();

        vm.prank(user);
        c.deposit{value: amount2}();

        // General rule: user's total deposited (amount1+amount2) equals contract balance + user's balance (if no withdrawals)
