pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user1, uint256 depositAmount, address user2, uint256 withdrawAmount) public {
        vm.assume(user1 != address(0) && user2 != address(0));
        vm.assume(user1 != user2);
        depositAmount = bound(depositAmount, 1, 1e18);
        withdrawAmount = bound(withdrawAmount, 0, 1e18);

        // user1 deposits
        vm.deal(user1, depositAmount);
        vm.prank(user1);
        c.deposit{value: depositAmount}();

        // user2 attempts to withdraw (bug: no balance check, may underflow)
        vm.prank(user2);
        c.withdraw(withdrawAmount);

        // Sum internal balances; no getter exists for mapping, so compute contract balance equality
        // After operations: c.balances is private, cannot read directly.
        // Instead, verify that c's balance is at least depositAmount (since user2's balance started at 0, 
        // and the bug may cause underflow which would revert or break invariant)
        // But the only public view is address(c).balance.
        // General rule: after any sequence, the contract balance should be >= sum of deposits - sum of withdrawals
        // Since user2 had no balance, a non-zero withdrawal in the buggy version would either revert (no transfer) 
        // or succeed and cause underflow (balance becomes huge). 
        // We'll check: if withdrawAmount > 0 and user2 had no deposit, the withdraw should revert.
        // For reference, it reverts (require fails). For mutant, it succeeds (no require).
        // So rule: calling withdraw with amount > user2's balance reverts.
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdraw(uint256)", withdrawAmount));
        if (withdrawAmount > 0) {
            assertTrue(!success, "Non-zero withdrawal from empty balance should revert");
        } else {
            assertTrue(success, "Zero withdrawal should succeed");
        }
    }
}

