import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= address(c).balance);
        vm.deal(address(c), 1 ether);
        uint256 balBefore = address(c).balance;
        // drive: deposit amount, then migrateTo
        c.deposit{value: amount}();
        address to = address(0x1234);
        uint256 balBeforeMigrate = address(c).balance;
        c.migrateTo(to);
        uint256 balAfter = address(c).balance;
        assertTrue(balBeforeMigrate == balAfter + (balBeforeMigrate - balAfter));
    }
}

